17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Objects;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final AddressNormalizer addressNormalizer;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper,
75	                                 AddressNormalizer addressNormalizer) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	        this.addressNormalizer = addressNormalizer;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String address = addressNormalizer.normalize(owner.getAddress());
114	        if (address.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        owner.setAddress(address);
118	        String telephone = toE164(owner.getTelephone());
119	        if (telephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setTelephone(telephone);
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        if (isDailyLimitReached()) {
127	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
128	        }
129	        if (isTelephoneInUse(telephone)) {
130	            return new ResponseEntity<>(HttpStatus.CONFLICT);
131	        }
132	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
133	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
134	            return new ResponseEntity<>(HttpStatus.CONFLICT);
135	        }
136	        if (sharesHousehold) {
137	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
138	        }
139	        if (isCityAtCapacity(owner.getCity())) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
143	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
144	        this.clinicService.saveOwner(owner);
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        headers.setLocation(UriComponentsBuilder.newInstance()
147	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
148	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
149	    }
150	
151	    /**
152	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
153	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
154	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
155	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
156	     */
157	    private String nextCustomerCode(String city, String lastName) {
158	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
159	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
160	        int sequence = (int) this.clinicService.findAllOwners().stream()
161	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
162	            .count() + 1;
163	        return String.format("%s-%s-%04d", city3, last3, sequence);
164	    }
165	
166	    /**
167	     * Whether the per-day owner creation limit has been reached, i.e. 100 or more owners have
168	     * already been created today (counted by their {@code registrationDate} matching the current
169	     * date). When true, a new owner must be rejected with {@code 429 Too Many Requests}.
170	     */
171	    private boolean isDailyLimitReached() {
172	        LocalDate today = LocalDate.now();
173	        long count = this.clinicService.findAllOwners().stream()
174	            .filter(existing -> today.equals(existing.getRegistrationDate()))
175	            .count();
176	        return count >= 100;
177	    }
178	
179	    /**
180	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
181	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
182	     */
183	    private boolean isCityAtCapacity(String city) {
184	        long count = this.clinicService.findAllOwners().stream()
185	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
186	            .count();
187	        return count >= 50;
188	    }
189	
190	    /**
191	     * The number of existing owners that already share the given firstName and lastName,
192	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
193	     * whitespace runs collapsed). Counted over the owners present before this create.
194	     */
195	    private int namesakeCount(String firstName, String lastName) {
196	        String candidateFirstName = normalizeName(firstName);
197	        String candidateLastName = normalizeName(lastName);
198	        return (int) this.clinicService.findAllOwners().stream()
199	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
200	                && normalizeName(existing.getLastName()).equals(candidateLastName))
201	            .count();
202	    }
203	
204	    /**
205	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
206	     * cannot form a valid E.164 number.
207	     *
208	     * <p>A leading '+' and country code are kept when present; otherwise country code
209	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
210	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
211	     * carry 8 to 15 digits after the '+'.
212	     */
213	    private String toE164(String telephone) {
214	        if (telephone == null) {
215	            return null;
216	        }
217	        boolean hasCountryCode = telephone.trim().startsWith("+");
218	        String digits = telephone.replaceAll("\\D", "");
219	        String e164;
220	        if (hasCountryCode) {
221	            e164 = digits;
222	        } else {
223	            if (digits.startsWith("0")) {
224	                digits = digits.substring(1);
225	            }
226	            e164 = "61" + digits;
227	        }
228	        if (e164.length() < 8 || e164.length() > 15) {
229	            return null;
230	        }
231	        return "+" + e164;
232	    }
233	
234	    /**
235	     * Whether any existing owner already holds the given telephone number. Both the
236	     * candidate and each stored number are compared in E.164 form, so the check does not
237	     * depend on how each was originally formatted.
238	     */
239	    private boolean isTelephoneInUse(String telephone) {
240	        return this.clinicService.findAllOwners().stream()
241	            .map(Owner::getTelephone)
242	            .filter(Objects::nonNull)
243	            .map(this::toE164)
244	            .filter(Objects::nonNull)
245	            .anyMatch(telephone::equals);
246	    }
247	
248	    /**
249	     * Whether any existing owner already shares a household with the candidate, i.e. has both
250	     * the same lastName and the same address. Both fields are compared case-insensitively and
251	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
252	     * trimmed), so the check does not depend on casing or spacing.
253	     */
254	    private boolean isHouseholdInUse(String lastName, String address) {
255	        String candidateLastName = normalizeName(lastName);
256	        String candidateAddress = addressNormalizer.normalize(address);
257	        return this.clinicService.findAllOwners().stream()
258	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
259	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
260	    }
261	
262	    /**
263	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
264	     * to a single space and lower-case. A null value normalizes to the empty string.
265	     */
266	    private String normalizeName(String value) {
267	        if (value == null) {
268	            return "";
269	        }
270	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
271	    }
272	
273	    /**
274	     * A stable shared identifier for the household formed by a given lastName and address.
275	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
276	     * lastName and address, so every owner sharing the same household is assigned the same
277	     * value regardless of the order in which they are created. Formatted as the first 12
278	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
279	     */
280	    private String householdId(String lastName, String address) {
281	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
282	        try {
283	            byte[] digest = MessageDigest.getInstance("SHA-256")
284	                .digest(key.getBytes(StandardCharsets.UTF_8));
285	            StringBuilder sb = new StringBuilder(digest.length * 2);
286	            for (byte b : digest) {
287	                sb.append(String.format("%02x", b));
288	            }
289	            return sb.substring(0, 12).toUpperCase();
290	        }
291	        catch (NoSuchAlgorithmException e) {
292	            throw new IllegalStateException("SHA-256 not available", e);
293	        }
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
